exec(compile('"""Rigid course/odometry alignment. Neither frame is PX4 NED."""\nimport math\nvector = core.vector\n\n\nclass CourseFrame:\n    """Map CAD coordinates onto startup odometry with measured yaw alignment.\n\n    yaw_offset is the course +X direction in odometry ENU, in radians. The\n    observed startup origin corresponds to the course\'s configured launch point.\n    Both frames must have aligned vertical axes (keep rig level at VO startup).\n    """\n    def __init__(self, course_start, odom_start, yaw_offset=0.0):\n        self.course_start = vector(course_start)\n        self.odom_start = vector(odom_start)\n        if not math.isfinite(yaw_offset):\n            raise ValueError(\'yaw_offset must be finite\')\n        self.yaw_offset = yaw_offset\n        self.c, self.s = math.cos(yaw_offset), math.sin(yaw_offset)\n\n    def velocity_to_odom(self, value):\n        x, y, z = vector(value)\n        return (self.c*x - self.s*y, self.s*x + self.c*y, z)\n\n    def velocity_to_course(self, value):\n        x, y, z = vector(value)\n        return (self.c*x + self.s*y, -self.s*x + self.c*y, z)\n\n    def position_to_odom(self, value):\n        delta = tuple(a-b for a, b in zip(vector(value), self.course_start))\n        return tuple(a+b for a, b in zip(self.odom_start, self.velocity_to_odom(delta)))\n\n    def position_to_course(self, value):\n        delta = tuple(a-b for a, b in zip(vector(value), self.odom_start))\n        return tuple(a+b for a, b in zip(self.course_start, self.velocity_to_course(delta)))\n\n\ndef rotate_body_velocity(quaternion, velocity):\n    """Rotate ROS FLU body velocity into odometry world using xyzw quaternion."""\n    x, y, z, w = (float(v) for v in quaternion)\n    n = math.sqrt(x*x+y*y+z*z+w*w)\n    if not math.isfinite(n) or n < 1e-6:\n        raise ValueError(\'invalid orientation quaternion\')\n    x, y, z, w = x/n, y/n, z/n, w/n\n    vx, vy, vz = vector(velocity)\n    return ((1-2*(y*y+z*z))*vx + 2*(x*y-z*w)*vy + 2*(x*z+y*w)*vz,\n            2*(x*y+z*w)*vx + (1-2*(x*x+z*z))*vy + 2*(y*z-x*w)*vz,\n            2*(x*z-y*w)*vx + 2*(y*z+x*w)*vy + (1-2*(x*x+y*y))*vz)\n', 'mission/frames.py', 'exec'), frames.__dict__)
COURSE = json.loads('{"name": "Gazebo X3 window approach speed profile", "source": "User-supplied preliminary OBJ, metres Z-up; measured race layout and official checkpoint scoring not validated", "start": [-2.5146, 0.9144, 0.0], "waypoints": [{"position": [-2.5146, 0.9144, 0.95], "phase": "TAKEOFF", "speed": 0.315}, {"position": [-2.5146, 2.53, 0.95], "phase": "FIRST_CORRIDOR", "speed": 0.49500000000000005}, {"position": [-1.32, 2.53, 0.95], "phase": "MAZE", "speed": 0.49500000000000005}, {"position": [-1.32, 1.03, 0.95], "phase": "MAZE", "speed": 0.49500000000000005}, {"position": [-0.2, 1.03, 0.95], "phase": "MAZE", "speed": 0.49500000000000005}, {"position": [-0.2, 2.53, 0.95], "phase": "MAZE", "speed": 0.49500000000000005}, {"position": [0.95, 2.53, 0.95], "phase": "GATE_A", "speed": 0.49500000000000005}, {"position": [2.3114, 2.2, 0.95], "phase": "TUNNEL_ALIGN", "speed": 0.75}, {"position": [2.3114, 1.6, 0.95], "phase": "TUNNEL_ALIGN", "speed": 0.5}, {"position": [2.3114, -0.72, 0.95], "phase": "TUNNEL", "speed": 0.85}, {"position": [2.13, -1.7, 0.95], "phase": "CHICANE", "speed": 0.7}, {"position": [0.3, -1.9, 0.95], "phase": "WINDOW_APPROACH", "speed": 0.39}, {"position": [0.045893, -2.460006, 0.762], "phase": "WINDOW_ALIGN", "speed": 0.20475000000000002}, {"position": [-0.987769, -2.083784, 0.762], "phase": "WINDOW_CROSS", "speed": 0.29250000000000004}, {"position": [-2.0422, -0.7925, 0.7], "phase": "LANDING_APPROACH", "speed": 0.65}], "limits": {"max_speed": 1.0, "max_accel": 0.8, "arrival_radius": 0.08, "odom_timeout": 0.25, "state_timeout": 0.6, "max_yaw_rate": 0.7}, "landing": {"position": [-2.0422, -0.7925, 0.0], "approach_height": 0.7}, "footprint_radius": 0.28, "footprint_note": "Conservative sphere proxy for geometry experiments only. This radius is an assumption, not a measured Skybeta envelope.", "bounds": {"min": [-3.048, -3.048, 0.0], "max": [3.048, 3.048, 3.048]}, "window": {"center": [-0.470938, -2.271895, 0.762], "normal_toward_entry": [0.9396926207859084, -0.3420201433256687, 0], "horizontal_axis": [0.3420201433256687, 0.9396926207859084, 0], "width": 0.9144, "height": 0.9144, "thickness": 0.1016, "source": "Inner aperture vertices of C2a chicane wall (window) in supplied OBJ; not field-calibrated"}}')

class WaypointMission(Node):
    def __init__(self):
        super().__init__('dronehacks_waypoints')
        p = self.declare_parameter
        p('speed_scale', 1.0)
        p('launch_heading_course_rad', math.pi / 2)
        p('rate_hz', 30.0)
        g = lambda n: self.get_parameter(n).value
        self.config = COURSE
        self.ctrl = core.CourseController(self.config, speed_scale=float(g('speed_scale')))
        self.launch_heading = float(g('launch_heading_course_rad'))
        self.frame = None
        self.odom = None
        self.odom_t = None
        self.state = {}
        self.state_t = None
        self.hold = None
        self.twist_pub = self.create_publisher(TwistStamped, '/skybeta/setpoint/twist', 10)
        self.pose_pub = self.create_publisher(PoseStamped, '/skybeta/setpoint/pose', 10)
        self.status_pub = self.create_publisher(String, '~/status', 10)
        self.create_subscription(Odometry, '/visual_slam/tracking/odometry', self.on_odom, 10)
        self.create_subscription(String, '/skybeta/state', self.on_state, 10)
        self.create_timer(1.0 / float(g('rate_hz')), self.tick)
        self.get_logger().info(f'dronehacks_waypoints ready: {len(self.ctrl.waypoints)} waypoints '
                               f'({self.config.get("name")}), speed scale {g("speed_scale")}. Waiting for Offboard...')

    def now(self):
        return self.get_clock().now().nanoseconds * 1e-9

    def on_odom(self, msg):
        self.odom, self.odom_t = msg, self.now()

    def on_state(self, msg):
        try:
            self.state = json.loads(msg.data)
            self.state_t = self.now()
        except ValueError:
            pass

    def send_pose(self, p_odom):
        m = PoseStamped()
        m.header.stamp = self.get_clock().now().to_msg()
        m.header.frame_id = 'odom'
        m.pose.position.x, m.pose.position.y, m.pose.position.z = (float(v) for v in p_odom)
        m.pose.orientation.w = 0.0                      # all-zero quaternion: do not command yaw
        self.pose_pub.publish(m)

    def tick(self):
        if self.odom is None or self.state_t is None:
            return
        pp, q = self.odom.pose.pose.position, self.odom.pose.pose.orientation
        p_odom = (pp.x, pp.y, pp.z)
        yaw_odom = math.atan2(2 * (q.w * q.z + q.x * q.y), 1 - 2 * (q.y * q.y + q.z * q.z))
        offboard = bool(self.state.get('offboard_active'))
        if self.hold is not None:
            self.send_pose(self.hold)
            return
        if self.frame is None:
            if not offboard:
                self.send_pose(p_odom)                  # stream "stay here" so Offboard can start
                return
            # course +X in odom = vehicle heading (course launch heading) rotated back
            self.frame = frames.CourseFrame(self.config['start'], p_odom, yaw_odom - self.launch_heading)
            self.get_logger().info(f'Offboard active: course frame anchored at odom {tuple(round(v, 3) for v in p_odom)}, '
                                   f'yaw offset {self.frame.yaw_offset:.3f} rad. Flying the route.')
        tw = self.odom.twist.twist.linear
        v_odom = frames.rotate_body_velocity((q.x, q.y, q.z, q.w), (tw.x, tw.y, tw.z))
        now = self.now()
        cmd = self.ctrl.update(self.frame.position_to_course(p_odom), self.frame.velocity_to_course(v_odom), now,
                               offboard=offboard, odom_age=now - self.odom_t, state_age=now - self.state_t,
                               yaw=core.wrap(yaw_odom - self.frame.yaw_offset))
        self.status_pub.publish(String(data=json.dumps({'phase': cmd.phase, 'done': cmd.done, 'fault': cmd.fault,
                                                        'waypoint': self.ctrl.waypoint_index,
                                                        'of': len(self.ctrl.waypoints)})))
        if cmd.fault:
            self.hold = p_odom
            self.get_logger().error(f'controller fault {cmd.fault} -- holding here.')
            return
        if cmd.done and math.dist(self.frame.position_to_course(p_odom), self.ctrl.handoff_target) <= self.ctrl.arrival_radius:
            self.hold = self.frame.position_to_odom(self.ctrl.handoff_target)
            self.get_logger().info('landing pad reached -- holding over it; the pilot lands.')
            return
        m = TwistStamped()
        m.header.stamp = self.get_clock().now().to_msg()
        m.header.frame_id = 'odom'
        m.twist.linear.x, m.twist.linear.y, m.twist.linear.z = self.frame.velocity_to_odom(cmd.velocity)
        m.twist.angular.z = float(cmd.yaw_rate)
        self.twist_pub.publish(m)


def main(args=None):
    rclpy.init(args=args)
    node = WaypointMission()
    try:
        rclpy.spin(node)
    except (KeyboardInterrupt, ExternalShutdownException):
        pass
    finally:
        node.destroy_node()
        rclpy.try_shutdown()


if __name__ == '__main__':
    main()
